def task_func(data, cols):
    df = pd.DataFrame(data, columns=cols)
    dbscan = DBSCAN(eps=3, min_samples=2)
    df['Cluster'] = dbscan.fit_predict(df)
    if len(cols) == 1 and len(set(df['Cluster']) - {-1}) > 1:
        labels = {label: i for i, label in enumerate(label for label in df['Cluster'].unique() if label != -1)}
        df['Cluster'] = df['Cluster'].map(lambda label: labels.get(label, -1))
    return df

import pandas as pd
from sklearn.cluster import DBSCAN

def task_func(data, cols):
    df = pd.DataFrame(data, columns=cols)
    dbscan = DBSCAN(eps=3, min_samples=2)
    labels = dbscan.fit_predict(df)
    if len(cols) == 1 and len(set(int(l) for l in labels if l != -1)) > 1:
        mapping = {}
        new_labels = []
        for l in labels:
            l = int(l)
            if l == -1:
                new_labels.append(-1)
            else:
                if l not in mapping:
                    mapping[l] = len(mapping)
                new_labels.append(mapping[l])
        labels = pd.Series(new_labels, index=df.index).astype(labels.dtype).values
    df['Cluster'] = labels
    return df

