import math

# Constants
POSSIBLE_NUMBERS = np.arange(1, 11)

def task_func(list_of_lists):
    sums = []
    for list_ in list_of_lists:
        if len(list_) > 10:
            sum_ = sum(math.pow(x, 2) for x in POSSIBLE_NUMBERS)
        else:
            sum_ = sum(math.pow(x, 2) for x in POSSIBLE_NUMBERS[:len(list_)])
